/**
 * Importing this module registers ~950 world cities with
 * `Location.lookup()` from `@hebcal/core`.
 */

/**
 * Maps a 2-letter ISO 3166-1 country code (e.g. `'AD'`) to its
 * English country name (e.g. `'Andorra'`).
 */
export declare const countryNames: Readonly<Record<string, string>>;

/**
 * Maps a 2-letter US state/territory code (e.g. `'CA'`) to its
 * English name (e.g. `'California'`).
 */
export declare const stateNames: Readonly<Record<string, string>>;
